/* From Uiverse.io by Yaya12085 - Source: https://uiverse.io/satyamchaudharydev/great-seahorse-44 - Tags: button, design, hover button */
.__UIV_SCOPE__ .button {
  width: fit-content;
  display: flex;
  padding: 1.2em 1rem;
  cursor: pointer;
  gap: 0.4rem;
  font-weight: bold;
  border-radius: 30px;
  text-shadow: 2px 2px 3px rgb(136 0 136 / 50%);
  background: linear-gradient(15deg, #880088, #aa2068, #cc3f47, #de6f3d, #f09f33, #de6f3d, #cc3f47, #aa2068, #880088) no-repeat;
  background-size: 300%;
  color: #fff;
  border: none;
  background-position: left center;
  box-shadow: 0 30px 10px -20px rgba(0,0,0,.2);
  transition: background .3s ease;
}

.__UIV_SCOPE__ .button:hover {
  background-size: 320%;
  background-position: right center;
}

.__UIV_SCOPE__ .button:hover svg {
  fill: #fff;
}

.__UIV_SCOPE__ .button svg {
  width: 23px;
  fill: #f09f33;
  transition: .3s ease;
}
